head='''import * as BunHttpServer from "@effect/platform-bun/BunHttpServer";
import * as BunServices from "@effect/platform-bun/BunServices";
import { describe, expect, it as test } from "@effect/vitest";
import { Array as EffectArray, Effect, FileSystem, Match, Option, Path, Result, Schema, Stream } from "effect";
import { ChildProcess, ChildProcessSpawner } from "effect/process";

import { ReleaseBoundaryFixtureCorpus } from "./schemas.js";

const repositoryRootUrl = new URL("../..", import.meta.url);

// The test scope owns each process and drains both pipes while waiting for its exit.
const runBoundaryCommand = Effect.fnUntraced(function* (
  cwd: string, executable: string, args: readonly string[], environment: Readonly<Record<string, string>> = {}
) {
  const spawner = yield* ChildProcessSpawner.ChildProcessSpawner;
  const child = yield* spawner.spawn(ChildProcess.make(executable, args, {
    cwd, env: environment, extendEnv: true, stderr: "pipe", stdin: "ignore", stdout: "pipe"
  }));
  const [exitCode, stderr, stdout] = yield* Effect.all([
    child.exitCode, Stream.mkString(Stream.decodeText(child.stderr)), Stream.mkString(Stream.decodeText(child.stdout))
  ], {concurrency: "unbounded"});
  return { exitCode, stderr, stdout };
});

// A scoped native server reserves an ephemeral address; it closes before the smoke command starts.
const findAvailableLoopbackPort = Effect.gen(function* () {
  const server = yield* BunHttpServer.make({ hostname: "127.0.0.1", port: 0 });
  return Match.value(server.address).pipe(
    Match.tags({
      InetAddressV4: (address) => address.port,
      InetAddressV6: (address) => address.port,
      UnixPathAddress: () => expect.unreachable(),
    }), Match.exhaustive
  );
}).pipe(Effect.scoped);

const prepareWorkspace = Effect.fnUntraced(function* (repositoryRoot: string) {
  const fs = yield* FileSystem.FileSystem;
  const path = yield* Path.Path;
  const workspace = yield* fs.makeTempDirectoryScoped({prefix: "taxkit-hgi205-boundaries-"});
  const inventory = yield* runBoundaryCommand(repositoryRoot, "git", ["ls-files", "--cached", "--others", "--exclude-standard"]);
  expect(inventory.exitCode).toBe(0);
  yield* Effect.forEach(EffectArray.filter(inventory.stdout.trim().split("\\n"), (relativePath) => relativePath.length > 0), (relativePath) => Effect.gen(function* () {
    const destination = path.join(workspace, relativePath);
    yield* fs.makeDirectory(path.dirname(destination), {recursive: true});
    const source = path.join(repositoryRoot, relativePath);
    // FileSystem.stat follows links in the installed platform. readLink preserves the exact relative target.
    // Only the host's EINVAL (ordinary file) falls back to copyFile; permission/missing/other errors fail.
    yield* fs.readLink(source).pipe(
      Effect.flatMap((target) => fs.symlink(target, destination)),
      Effect.catchTag("PlatformError", (error) =>
        error.reason._tag === "Unknown" && Result.isSuccess(Schema.decodeUnknownResult(Schema.Struct({code: Schema.Literal("EINVAL")}))(error.reason.cause))
          ? fs.copyFile(source, destination) : Effect.fail(error)
      )
    );
  }), {concurrency: 16});
  const install = yield* runBoundaryCommand(workspace, "bun", ["install", "--offline", "--frozen-lockfile", "--linker=hoisted"]);
  expect(install.exitCode, `Offline frozen fixture install failed in ${workspace}:\\n${install.stderr}\\n${install.stdout}`).toBe(0);
  const workspacePackages = [
    ["api-http", "packages/api/http"], ["calculators", "packages/calculators"], ["core", "packages/core"],
    ["rules-au-income-tax", "packages/rules/au/income-tax"], ["rules-au-pay", "packages/rules/au/pay"],
    ["rules-au-stsl", "packages/rules/au/stsl"], ["scripts", "packages/scripts"], ["sdk", "packages/sdk/typescript"],
    ["testing", "packages/testing"], ["tsconfig", "packages/tsconfig"]
  ] as const;
  yield* Effect.forEach([
    {scope: path.join(workspace, "node_modules", "@taxkit"), prefix: ["..", ".."]},
    {scope: path.join(workspace, "apps", "api", "node_modules", "@taxkit"), prefix: ["..", "..", "..", ".."]}
  ], ({scope, prefix}) => Effect.gen(function* () {
    yield* fs.makeDirectory(scope, {recursive: true});
    yield* Effect.forEach(workspacePackages, ([name, packageRoot]) => Effect.gen(function* () {
      const alias = path.join(scope, name);
      yield* fs.remove(alias, {force: true, recursive: true});
      yield* fs.symlink(path.join(...prefix, packageRoot), alias);
    }));
  }));
  return workspace;
});

'''
tail='''describe("HGI-205 isolated release-boundary mutations", () => {
  test.effect("executes every real owning command and retains exact failure identity", () =>
    Effect.gen(function* () {
      const fs = yield* FileSystem.FileSystem;
      const path = yield* Path.Path;
      const repositoryRoot = yield* path.fromFileUrl(repositoryRootUrl);
      const fixtures = yield* fs.readFileString(path.join(repositoryRoot, "tools/quality-workflow/fixtures/release-boundary-defects.json")).pipe(
        Effect.flatMap(Schema.decodeEffect(Schema.fromJsonString(ReleaseBoundaryFixtureCorpus), {onExcessProperty: "error"}))
      );
      yield* Effect.forEach(fixtures, (fixture) => Effect.gen(function* () {
        const workspace = yield* prepareWorkspace(repositoryRoot);
        const contract = Match.value(fixture.id).pipe(
          Match.when("api-contract", () => expected["api-contract"]),
          Match.when("packed-sdk", () => expected["packed-sdk"]),
          Match.when("public-docs-manifest", () => expected["public-docs-manifest"]),
          Match.when("public-export", () => expected["public-export"]),
          Match.when("release-script", () => expected["release-script"]),
          Match.when("workflow-semantics", () => expected["workflow-semantics"]),
          Match.exhaustive
        );
        expect(fixture.expectedFailedCheck).toBe(contract.check);
        expect(fixture.target).toBe(contract.target);
        expect(fixture.recovery).toBe(contract.recovery);
        expect([fixture.command.executable, ...fixture.command.args]).toEqual(contract.command);
        expect(fixture.runner).toBe("tools/quality-workflow/release-boundary.test.ts");
        const target = path.join(workspace, fixture.target);
        const source = yield* fs.readFileString(target);
        expect(source.includes(fixture.mutation.search)).toBe(true);
        yield* fs.writeFileString(target, source.replaceAll(fixture.mutation.search, fixture.mutation.replacement));
        if (fixture.id === "api-contract") {
          const build = yield* runBoundaryCommand(workspace, "bun", ["run", "build", "--filter=api...", "--force"]);
          expect(build.exitCode, `${build.stderr}\\n${build.stdout}`).toBe(0);
        }
        const environment = fixture.id === "api-contract" ? { TAXKIT_API_SMOKE_PORT: String(yield* findAvailableLoopbackPort) } : {};
        const result = yield* runBoundaryCommand(workspace, fixture.command.executable, fixture.command.args, environment);
        yield* fs.writeFileString(target, source);
        expect(result.exitCode).not.toBe(0);
        expect(`${result.stdout}\\n${result.stderr}`).toContain(fixture.failureOracle);
      }).pipe(Effect.scoped));
    }).pipe(Effect.provide(BunServices.layer)), 300_000
  );
});
